/**
 * Argument tuples of every imgproxy info option, by canonical name.
 * `/rs:fill:300:400/` is `{ resize: ["fill", 300, 400] }`: `null` is an empty
 * argument, booleans are written `1`/`0`.
 */
export interface ImgproxyInfoArgs {
  /**
   * Report whether the source has alpha. URL: `alpha`, `a`; arguments alpha:check_transparency; default false:false.
   *
   * URL names: `alpha`, `a`.
   * milestone M1; scope request.
   * @example [true]
   */
  "alpha":
    | [alpha: boolean | null, check_transparency?: boolean | null];
  /**
   * Report the average colour. URL: `average`, `avg`; arguments enabled:ignore_transparent; default false:true.
   *
   * URL names: `average`, `avg`.
   * milestone M2; scope request.
   * @example [true,true]
   */
  "average":
    | [enabled: boolean | null, ignore_transparent?: boolean | null];
  /**
   * Report the number of bands. URL: `bands`, `b`; arguments bool; default false.
   *
   * URL names: `bands`, `b`.
   * milestone M1; scope request.
   * @example [true]
   */
  "bands":
    | [bands: boolean | null];
  /**
   * Report a BlurHash. URL: `blurhash`, `bh`; arguments x:y (1..9 each, 0:0 off); default 0:0.
   *
   * URL names: `blurhash`, `bh`.
   * milestone M2; scope request.
   * @example [4,3]
   */
  "blurhash":
    | [x_components: number, y_components: number];
  /**
   * Skip the result cache (XI_CACHE_ALLOW_BYPASS). URL: `bypass_cache`, `bc`; arguments bool; default false.
   *
   * URL names: `bypass_cache`, `bc`.
   * milestone M2 (WP-52); scope request; imgproxy Pro option (free here).
   * @example [true]
   */
  "bypass_cache":
    | [bypass: boolean | null];
  /**
   * Tags for the Cache-Tag response header. URL: `cache_tags`, `ct`; arguments tags… (visible ASCII, no commas; replaces earlier tags); default —.
   *
   * URL names: `cache_tags`, `ct`.
   * milestone M2 (WP-34b, WP-64 end-to-end test); scope request; imgproxy Pro option (free here).
   * @example ["product","hero"]
   */
  "cache_tags":
    | [tag: string | null, ...tags: Array<string | null>];
  /**
   * Changes the URL, the cache key and the ETag. URL: `cachebuster`, `cb`; arguments string; default —.
   *
   * URL names: `cachebuster`, `cb`.
   * milestone M1; scope request.
   * @example ["v2"]
   */
  "cachebuster":
    | [value: string | null];
  /**
   * Report source digests. URL: `calc_hashsums`, `chs`; arguments md5, sha1, sha256, sha512…; default —.
   *
   * URL names: `calc_hashsums`, `chs`.
   * milestone M2; scope request.
   * @example ["md5","sha256"]
   */
  "calc_hashsums":
    | [type: "md5" | "sha1" | "sha256" | "sha512" | null, ...types: Array<"md5" | "sha1" | "sha256" | "sha512" | null>];
  /**
   * Classify the image. URL: `classify`, `cl`; arguments top_k:classes…; default 0.
   *
   * URL names: `classify`, `cl`.
   * milestone M3; scope request; imgproxy Pro option (free here).
   * @example [3]
   */
  "classify":
    | [top_k: number, ...classes: Array<string>];
  /**
   * Report the libvips interpretation. URL: `colorspace`, `cs`; arguments bool; default false.
   *
   * URL names: `colorspace`, `cs`.
   * milestone M1; scope request.
   * @example [true]
   */
  "colorspace":
    | [colorspace: boolean | null];
  /**
   * Report the crop area. URL: `crop`, `c`; arguments w:h:gravity (as processing `crop`); default —.
   *
   * URL names: `crop`, `c`.
   * milestone M2; scope request.
   * @example [300,200,"sm"]
   */
  "crop":
    | [width: number, height?: number, type?: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe" | null, x_offset?: number | null, y_offset?: number | null]
    | [width: number, height?: number, type?: "sm"]
    | [width: number, height: number, type: "fp", x: number, y: number]
    | [width: number, height?: number, type?: "obj", ...classes: Array<string>]
    | [width: number, height: number, type: "objw", class_or_weight: string | number, class_or_weight_2: string | number, ...class_or_weights: Array<string | number>];
  /**
   * Report detected objects. URL: `detect_objects`, `do`; arguments bool; default false.
   *
   * URL names: `detect_objects`, `do`.
   * milestone M3; scope request; imgproxy Pro option (free here).
   * @example [true]
   */
  "detect_objects":
    | [detect_objects: boolean | null];
  /**
   * Report width, height and orientation. URL: `dimensions`, `d`; arguments bool; default true.
   *
   * URL names: `dimensions`, `d`.
   * milestone M1; scope request.
   * @example [true]
   */
  "dimensions":
    | [dimensions: boolean | null];
  /**
   * Report dominant colours. URL: `dominant_colors`, `dc`; arguments enabled:build_missed; default false:false.
   *
   * URL names: `dominant_colors`, `dc`.
   * milestone M2; scope request.
   * @example [true,false]
   */
  "dominant_colors":
    | [enabled: boolean | null, build_missed?: boolean | null];
  /**
   * Report EXIF tags. URL: `exif`; arguments enabled:canonical_names; default true:false.
   *
   * URL names: `exif`.
   * milestone M1; scope request.
   * @example [true,false]
   */
  "exif":
    | [enabled: boolean | null, canonical_names?: boolean | null];
  /**
   * URL expiry (404 afterwards). URL: `expires`, `exp`; arguments unix ts; default —.
   *
   * URL names: `expires`, `exp`.
   * milestone M1; scope request.
   * @example [4102444800]
   */
  "expires":
    | [timestamp: number];
  /**
   * Report the format and media type. URL: `format`, `f`; arguments bool; default true.
   *
   * URL names: `format`, `f`.
   * milestone M1; scope request.
   * @example [true]
   */
  "format":
    | [format: boolean | null];
  /**
   * Check the source bytes against a digest. URL: `hashsum`, `hs`; arguments none, or md5/sha1/sha256/sha512:hex; default none.
   *
   * URL names: `hashsum`, `hs`.
   * milestone M2 (WP-64); scope request; imgproxy Pro option (free here).
   * @example ["sha256","e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"]
   */
  "hashsum":
    | [type: "none" | "md5" | "sha1" | "sha256" | "sha512" | null, hashsum?: string | null];
  /**
   * Report IPTC datasets (and Photoshop resolution). URL: `iptc`; arguments bool; default true.
   *
   * URL names: `iptc`.
   * milestone M1; scope request.
   * @example [true]
   */
  "iptc":
    | [iptc: boolean | null];
  /**
   * Lower (or raise) the source size limit. URL: `max_src_file_size`, `msfs`; arguments int; default config. Needs XI_SECURITY_ALLOW_SECURITY_OPTIONS (403 otherwise).
   *
   * URL names: `max_src_file_size`, `msfs`.
   * milestone M1; scope request; security option (needs XI_SECURITY_ALLOW_SECURITY_OPTIONS).
   * @example [10]
   */
  "max_src_file_size":
    | [bytes: number];
  /**
   * Lower (or raise) the source resolution limit. URL: `max_src_resolution`, `msr`; arguments int; default config. Needs XI_SECURITY_ALLOW_SECURITY_OPTIONS (403 otherwise).
   *
   * URL names: `max_src_resolution`, `msr`.
   * milestone M1; scope request; security option (needs XI_SECURITY_ALLOW_SECURITY_OPTIONS).
   * @example [10]
   */
  "max_src_resolution":
    | [megapixels: number];
  /**
   * Objects position for the reported crop. URL: `objects_position`, `obj_pos`, `op`; arguments as processing; default ce:0:0.
   *
   * URL names: `objects_position`, `obj_pos`, `op`.
   * milestone M3; scope request; imgproxy Pro option (free here).
   * @example ["prop"]
   */
  "objects_position":
    | [type: "ce" | "no" | "so" | "ea" | "we" | "noea" | "nowe" | "soea" | "sowe", x_offset?: number | null, y_offset?: number | null]
    | [type: "fp", x?: number | null, y?: number | null]
    | [type: "prop"];
  /**
   * First page of a multi-page source. URL: `page`, `pg`; arguments int; default 0.
   *
   * URL names: `page`, `pg`.
   * milestone M2 (WP-50, WP-62); scope pipeline; imgproxy Pro option (free here).
   * @example [1]
   */
  "page":
    | [page: number];
  /**
   * Report the number of pages or frames. URL: `pages_number`, `pn`; arguments bool; default false.
   *
   * URL names: `pages_number`, `pn`.
   * milestone M1; scope request.
   * @example [true]
   */
  "pages_number":
    | [pages_number: boolean | null];
  /**
   * Report a palette. URL: `palette`, `p`; arguments 0 or 2..256; default 0.
   *
   * URL names: `palette`, `p`.
   * milestone M2; scope request.
   * @example [16]
   */
  "palette":
    | [colors: number];
  /**
   * Report a perceptual hash. URL: `perceptual_hash`, `phash`, `ph`; arguments bool; default false.
   *
   * URL names: `perceptual_hash`, `phash`, `ph`.
   * milestone M2; scope request.
   * @example [true]
   */
  "perceptual_hash":
    | [perceptual_hash: boolean | null];
  /**
   * Expand presets in place. URL: `preset`, `pr`; arguments names…; default —.
   *
   * URL names: `preset`, `pr`.
   * milestone M1; scope pipeline.
   * @example ["thumbnail"]
   */
  "preset":
    | [name: string, ...names: Array<string>];
  /**
   * Report the libvips band format. URL: `sample_format`, `sf`; arguments bool; default false.
   *
   * URL names: `sample_format`, `sf`.
   * milestone M1; scope request.
   * @example [true]
   */
  "sample_format":
    | [sample_format: boolean | null];
  /**
   * Report the source size in bytes. URL: `size`, `s`; arguments bool; default true.
   *
   * URL names: `size`, `s`.
   * milestone M1; scope request.
   * @example [true]
   */
  "size":
    | [size: boolean | null];
  /**
   * Report a ThumbHash. URL: `thumbhash`, `thumb_hash`, `th`; arguments bool; default false.
   *
   * URL names: `thumbhash`, `thumb_hash`, `th`.
   * milestone M2; scope request.
   * @example [true]
   */
  "thumbhash":
    | [thumbhash: boolean | null];
  /**
   * Report video metadata. URL: `video_meta`, `vm`; arguments bool; default true.
   *
   * URL names: `video_meta`, `vm`.
   * milestone M3; scope request.
   * @example [true]
   */
  "video_meta":
    | [video_meta: boolean | null];
  /**
   * Seek to keyframes only. URL: `video_thumbnail_keyframes`, `vtk`; arguments bool; default config.
   *
   * URL names: `video_thumbnail_keyframes`, `vtk`.
   * milestone M3; scope pipeline; imgproxy Pro option (free here).
   * @example [true]
   */
  "video_thumbnail_keyframes":
    | [keyframes: boolean | null];
  /**
   * Video frame to use as the image. URL: `video_thumbnail_second`, `vts`; arguments float; default config.
   *
   * URL names: `video_thumbnail_second`, `vts`.
   * milestone M3; scope pipeline; imgproxy Pro option (free here).
   * @example [5]
   */
  "video_thumbnail_second":
    | [second: number];
  /**
   * Report XMP properties. URL: `xmp`; arguments bool; default true.
   *
   * URL names: `xmp`.
   * milestone M1; scope request.
   * @example [true]
   */
  "xmp":
    | [xmp: boolean | null];
}

